create extension if not exists pgcrypto;

create table if not exists public.angelcare_marketplace_approval_requests(
 id uuid primary key default gen_random_uuid(), public_reference text unique not null default ('APR-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))), object_type text not null, object_id text not null, title text not null, summary text, status text not null default 'submitted' check(status in('draft','submitted','in_review','approved','rejected','cancelled','expired')), priority text not null default 'normal' check(priority in('low','normal','high','critical')), requested_by uuid, owner_id uuid, territory_id uuid, tenant_id uuid, current_step int not null default 1, required_steps int not null default 1, due_at timestamptz, submitted_at timestamptz default now(), decision_reason text, decided_by uuid, decided_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.angelcare_marketplace_approval_steps(id uuid primary key default gen_random_uuid(),approval_id uuid not null references public.angelcare_marketplace_approval_requests(id) on delete cascade,step_order int not null,role_key text not null,status text not null default 'pending',required boolean not null default true,reviewer_id uuid,completed_at timestamptz,unique(approval_id,step_order));
create table if not exists public.angelcare_marketplace_approval_decisions(id uuid primary key default gen_random_uuid(),approval_id uuid not null references public.angelcare_marketplace_approval_requests(id) on delete cascade,decision text not null check(decision in('approved','rejected')),reason text not null,actor_id uuid,created_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_admin_action_items(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('ACT-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),title text not null,description text,object_type text,object_id text,status text not null default 'open' check(status in('open','in_progress','blocked','completed','cancelled')),priority text not null default 'normal' check(priority in('low','normal','high','critical')),owner_id uuid,assignee_id uuid,owner_role text,territory_id uuid,tenant_id uuid,due_at timestamptz,blocker text,next_action text,created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),completed_at timestamptz);
create table if not exists public.angelcare_marketplace_executive_briefs(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('BRF-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),title text not null,summary text not null,status text not null default 'draft' check(status in('draft','review','published','archived')),territory_id uuid,owner_id uuid,period_start date,period_end date,risks jsonb not null default '[]',decisions jsonb not null default '[]',evidence jsonb not null default '[]',published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_admin_comments(id uuid primary key default gen_random_uuid(),object_type text not null,object_id text not null,body text not null,visibility text not null default 'internal' check(visibility in('internal','restricted')),author_id uuid,created_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_object_relations(id uuid primary key default gen_random_uuid(),source_object_type text not null,source_object_id text not null,target_object_type text not null,target_object_id text not null,relation_type text not null,created_by uuid,created_at timestamptz not null default now(),unique(source_object_type,source_object_id,target_object_type,target_object_id,relation_type));
create table if not exists public.angelcare_marketplace_admin_saved_views(id uuid primary key default gen_random_uuid(),name text not null,domain text not null,filters jsonb not null default '{}',owner_id uuid,shared boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());

create or replace function public.angelcare_marketplace_create_approval_request(p_object_type text,p_object_id text,p_title text,p_summary text,p_priority text,p_owner_id uuid,p_requested_by uuid,p_territory_id uuid,p_due_at timestamptz) returns public.angelcare_marketplace_approval_requests language plpgsql security definer set search_path=public as $$declare r public.angelcare_marketplace_approval_requests;begin insert into public.angelcare_marketplace_approval_requests(object_type,object_id,title,summary,priority,owner_id,requested_by,territory_id,due_at,status) values(p_object_type,p_object_id,p_title,p_summary,coalesce(p_priority,'normal'),p_owner_id,p_requested_by,p_territory_id,p_due_at,'submitted') returning * into r;return r;end$$;
create or replace function public.angelcare_marketplace_decide_approval(p_approval_id uuid,p_decision text,p_reason text,p_actor_id uuid) returns public.angelcare_marketplace_approval_requests language plpgsql security definer set search_path=public as $$declare r public.angelcare_marketplace_approval_requests;begin if p_decision not in('approved','rejected') then raise exception 'Invalid decision';end if;update public.angelcare_marketplace_approval_requests set status=p_decision,decision_reason=p_reason,decided_by=p_actor_id,decided_at=now(),updated_at=now() where id=p_approval_id and status in('submitted','in_review') returning * into r;if r.id is null then raise exception 'Approval is not decidable';end if;insert into public.angelcare_marketplace_approval_decisions(approval_id,decision,reason,actor_id)values(p_approval_id,p_decision,p_reason,p_actor_id);return r;end$$;

create or replace view public.angelcare_marketplace_admin_search_v as
select 'module'::text object_type,m.id::text object_id,m.module_key public_reference,m.name title,coalesce(m.description,'') subtitle,m.status,m.owner_role::text owner_id,null::uuid territory_id,null::uuid tenant_id,m.route_prefix route, setweight(to_tsvector('simple',coalesce(m.name,'')),'A')||setweight(to_tsvector('simple',coalesce(m.description,'')),'B') search_document,1::real search_rank,m.updated_at from public.angelcare_marketplace_modules m
union all select 'territory',t.id::text,t.territory_code,t.name,t.country_code,t.status,t.owner_id::text,t.id,null::uuid,'/angelcare-marketplace/admin/territories/'||t.territory_code,to_tsvector('simple',coalesce(t.name,'')||' '||coalesce(t.territory_code,'')),1::real,t.updated_at from public.angelcare_marketplace_territories t;

create index if not exists angelcare_marketplace_approvals_status_idx on public.angelcare_marketplace_approval_requests(status,priority,created_at desc);
create index if not exists angelcare_marketplace_actions_status_idx on public.angelcare_marketplace_admin_action_items(status,priority,due_at);
create index if not exists angelcare_marketplace_comments_object_idx on public.angelcare_marketplace_admin_comments(object_type,object_id,created_at desc);

insert into public.angelcare_marketplace_permissions(permission_key,name,category,sensitive) values
('marketplace.backoffice.cockpit.view','Voir le Commandement 360','Master Backoffice',false),('marketplace.backoffice.command.view','Voir le Commandement 360','Master Backoffice',false),('marketplace.backoffice.search','Utiliser la recherche globale','Master Backoffice',false),('marketplace.backoffice.approvals.view','Voir les approbations','Master Backoffice',false),('marketplace.backoffice.approvals.create','Créer une approbation','Master Backoffice',true),('marketplace.backoffice.approvals.review','Réviser une approbation','Master Backoffice',true),('marketplace.backoffice.approvals.decide','Décider une approbation','Master Backoffice',true),('marketplace.backoffice.approvals.override','Déroger à une approbation','Master Backoffice',true),('marketplace.backoffice.actions.view','Voir les actions','Master Backoffice',false),('marketplace.backoffice.actions.manage','Gérer les actions','Master Backoffice',true),('marketplace.backoffice.objects.view','Voir les dossiers objets','Master Backoffice',false),('marketplace.backoffice.objects.comment','Commenter les dossiers','Master Backoffice',true),('marketplace.backoffice.objects.export','Exporter les dossiers objets','Master Backoffice',true),('marketplace.backoffice.briefs.view','Voir les briefs','Master Backoffice',false),('marketplace.backoffice.briefs.create','Créer les briefs','Master Backoffice',true),('marketplace.backoffice.briefs.publish','Publier les briefs','Master Backoffice',true),('marketplace.backoffice.briefs.manage','Gérer les briefs','Master Backoffice',true),('marketplace.backoffice.audit.export','Exporter les preuves','Master Backoffice',true)
on conflict(permission_key) do update set name=excluded.name,category=excluded.category,sensitive=excluded.sensitive;
insert into public.angelcare_marketplace_role_permissions(role_key,permission_key) select r.role_key,p.permission_key from public.angelcare_marketplace_roles r cross join public.angelcare_marketplace_permissions p where r.role_key in('marketplace_super_admin','marketplace_executive') and p.permission_key like 'marketplace.backoffice.%' on conflict do nothing;
update public.angelcare_marketplace_modules set status='enabled',enabled=true,health_status='healthy',route_prefix='/angelcare-marketplace/admin/command',required_permissions=array['marketplace.backoffice.cockpit.view']::text[],version=version+1,updated_at=now() where introduced_by_mega_zip=4;
insert into public.angelcare_marketplace_feature_flags(flag_key,name,description,enabled,status,reason) values('marketplace.master-backoffice.enabled','Master Backoffice souverain','Commandement, recherche, décisions, actions et dossiers.',true,'active','Ultra Delivery 1/5') on conflict(flag_key) do update set enabled=true,status='active',updated_at=now();

alter table public.angelcare_marketplace_approval_requests enable row level security;alter table public.angelcare_marketplace_approval_steps enable row level security;alter table public.angelcare_marketplace_approval_decisions enable row level security;alter table public.angelcare_marketplace_admin_action_items enable row level security;alter table public.angelcare_marketplace_executive_briefs enable row level security;alter table public.angelcare_marketplace_admin_comments enable row level security;alter table public.angelcare_marketplace_object_relations enable row level security;alter table public.angelcare_marketplace_admin_saved_views enable row level security;
revoke all on table public.angelcare_marketplace_approval_requests,public.angelcare_marketplace_approval_steps,public.angelcare_marketplace_approval_decisions,public.angelcare_marketplace_admin_action_items,public.angelcare_marketplace_executive_briefs,public.angelcare_marketplace_admin_comments,public.angelcare_marketplace_object_relations,public.angelcare_marketplace_admin_saved_views from anon,authenticated;
grant all on table public.angelcare_marketplace_approval_requests,public.angelcare_marketplace_approval_steps,public.angelcare_marketplace_approval_decisions,public.angelcare_marketplace_admin_action_items,public.angelcare_marketplace_executive_briefs,public.angelcare_marketplace_admin_comments,public.angelcare_marketplace_object_relations,public.angelcare_marketplace_admin_saved_views to service_role;
grant execute on function public.angelcare_marketplace_create_approval_request(text,text,text,text,text,uuid,uuid,uuid,timestamptz),public.angelcare_marketplace_decide_approval(uuid,text,text,uuid) to service_role;
